arguments.command:
bundle exec rails runner -e test '
require "fabrication"
require Rails.root.join("spec/support/signing_keys_helpers").to_s
Sidekiq.testing!(:fake)
Chewy.strategy(:bypass)
Setting.registrations_mode = "open"
def attachment_fixture(name) = Rails.root.join("spec", "fixtures", "files", name).open
Fabrication.manager.load_definitions

def bench(label, n = 40)
  # warmup
  ActiveRecord::Base.transaction { yield; raise ActiveRecord::Rollback }
  t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
  ActiveRecord::Base.transaction do
    n.times { yield }
    raise ActiveRecord::Rollback
  end
  ms = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0) / n * 1000
  puts format("%-55s %6.2f ms/call", label, ms)
end

bench("account (default: with user + keypair)") { Fabricate(:account) }
bench("account (user: nil, with keypair)") { Fabricate(:account, user: nil) }
bench("account (user: nil, legacy_keypair: true)") { Fabricate(:account, user: nil, legacy_keypair: true) }
bench("remote_account (default: with keypair)") { Fabricate(:remote_account) }
bench("remote_account (legacy_keypair: true)") { Fabricate(:remote_account, legacy_keypair: true) }
bench("user (default: with account + 2 login_activities)") { Fabricate(:user) }
acc = nil
ActiveRecord::Base.transaction do
  acc = Fabricate(:account)
  bench("status (default: new account + bookmark)") { Fabricate(:status) }
  bench("status (existing account, still + bookmark)") { Fabricate(:status, account: acc) }
  bench("media_attachment (default: new account + 60KB jpg)", 15) { Fabricate(:media_attachment) }
  bench("media_attachment (existing account + 60KB jpg)", 15) { Fabricate(:media_attachment, account: acc) }
  bench("media_attachment (existing account + mini-static.gif)", 15) { Fabricate(:media_attachment, account: acc, file: attachment_fixture("mini-static.gif")) }
  bench("preview_card (default: with 60KB jpg)", 15) { Fabricate(:preview_card) }
  bench("preview_card (image: nil)", 15) { Fabricate(:preview_card, image: nil) }
  bench("preview_card (mini-static.gif)", 15) { Fabricate(:preview_card, image: attachment_fixture("mini-static.gif")) }
  bench("custom_emoji (default: 29KB emojo.png)", 15) { Fabricate(:custom_emoji) }
  bench("custom_emoji (mini-static.gif)", 15) { Fabricate(:custom_emoji, image: attachment_fixture("mini-static.gif")) }
  raise ActiveRecord::Rollback
end
'

